-- Disposable PostgreSQL 18 contract test for a least-privilege logical backup role.
-- Exercises explicit grants on existing objects and default SELECT grants for
-- future tables/sequences created by the application-object owner.
-- Run only against the ephemeral CI service. No external database or secrets.
BEGIN;

CREATE ROLE backup_contract_test LOGIN PASSWORD 'backup-contract-test-only'
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT;
CREATE ROLE backup_contract_owner NOLOGIN
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT;
CREATE SCHEMA backup_contract_fixture AUTHORIZATION backup_contract_owner;

GRANT CONNECT ON DATABASE microapp_test TO backup_contract_test;
GRANT USAGE ON SCHEMA backup_contract_fixture TO backup_contract_test;

-- This is the exact future-object policy proposed for a dedicated backup role.
ALTER DEFAULT PRIVILEGES FOR ROLE backup_contract_owner
  IN SCHEMA backup_contract_fixture
  GRANT SELECT ON TABLES TO backup_contract_test;
ALTER DEFAULT PRIVILEGES FOR ROLE backup_contract_owner
  IN SCHEMA backup_contract_fixture
  GRANT SELECT ON SEQUENCES TO backup_contract_test;

-- Create an existing object and future objects under the same owner, after
-- default ACLs are installed. The explicit GRANTs below model migration/bootstrap
-- grants for objects that predate the backup role.
SET ROLE backup_contract_owner;
CREATE TABLE backup_contract_fixture.existing_sample (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payload text NOT NULL
);
INSERT INTO backup_contract_fixture.existing_sample (payload)
VALUES ('synthetic-backup-fixture');
CREATE TABLE backup_contract_fixture.future_sample (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payload text NOT NULL
);
CREATE SEQUENCE backup_contract_fixture.future_sequence;
RESET ROLE;

GRANT SELECT ON ALL TABLES IN SCHEMA backup_contract_fixture TO backup_contract_test;
GRANT SELECT ON ALL SEQUENCES IN SCHEMA backup_contract_fixture TO backup_contract_test;

DO $assert_backup_contract$
DECLARE
  role_row record;
  owner_oid oid;
  role_oid oid;
BEGIN
  SELECT * INTO role_row FROM pg_catalog.pg_roles WHERE rolname = 'backup_contract_test';
  IF NOT FOUND OR NOT role_row.rolcanlogin OR role_row.rolsuper OR role_row.rolcreaterole
     OR role_row.rolcreatedb OR role_row.rolreplication OR role_row.rolbypassrls
     OR role_row.rolinherit THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_ROLE_ATTRIBUTES_FAILED';
  END IF;

  SELECT oid INTO role_oid FROM pg_catalog.pg_roles WHERE rolname = 'backup_contract_test';
  SELECT oid INTO owner_oid FROM pg_catalog.pg_roles WHERE rolname = 'backup_contract_owner';
  IF EXISTS (
    SELECT 1 FROM pg_catalog.pg_auth_members
    WHERE member IN (role_oid, owner_oid) OR roleid IN (role_oid, owner_oid)
  ) THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_ROLE_MEMBERSHIP_FAILED';
  END IF;

  IF NOT pg_catalog.has_database_privilege('backup_contract_test', current_database(), 'CONNECT')
     OR pg_catalog.has_database_privilege('backup_contract_test', current_database(), 'CREATE')
     OR NOT pg_catalog.has_schema_privilege('backup_contract_test', 'backup_contract_fixture', 'USAGE')
     OR pg_catalog.has_schema_privilege('backup_contract_test', 'backup_contract_fixture', 'CREATE') THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_DATABASE_OR_SCHEMA_PRIVILEGES_FAILED';
  END IF;

  IF NOT pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample', 'SELECT')
     OR NOT pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.future_sample', 'SELECT')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample', 'INSERT')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample', 'UPDATE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample', 'DELETE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample', 'TRUNCATE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.future_sample', 'INSERT')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.future_sample', 'UPDATE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.future_sample', 'DELETE')
     OR pg_catalog.has_table_privilege('backup_contract_test', 'backup_contract_fixture.future_sample', 'TRUNCATE') THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_TABLE_PRIVILEGES_FAILED';
  END IF;

  IF NOT pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample_id_seq', 'SELECT')
     OR NOT pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.future_sample_id_seq', 'SELECT')
     OR NOT pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.future_sequence', 'SELECT')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample_id_seq', 'USAGE')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.existing_sample_id_seq', 'UPDATE')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.future_sample_id_seq', 'USAGE')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.future_sample_id_seq', 'UPDATE')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.future_sequence', 'USAGE')
     OR pg_catalog.has_sequence_privilege('backup_contract_test', 'backup_contract_fixture.future_sequence', 'UPDATE') THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_SEQUENCE_PRIVILEGES_FAILED';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_default_acl d
    JOIN pg_catalog.pg_roles owner_role ON owner_role.oid=d.defaclrole
    CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) acl
    WHERE owner_role.rolname='backup_contract_owner'
      AND d.defaclnamespace='backup_contract_fixture'::regnamespace
      AND d.defaclobjtype='r'
      AND acl.grantee=role_oid AND acl.privilege_type='SELECT'
  ) OR NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_default_acl d
    JOIN pg_catalog.pg_roles owner_role ON owner_role.oid=d.defaclrole
    CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) acl
    WHERE owner_role.rolname='backup_contract_owner'
      AND d.defaclnamespace='backup_contract_fixture'::regnamespace
      AND d.defaclobjtype='S'
      AND acl.grantee=role_oid AND acl.privilege_type='SELECT'
  ) THEN
    RAISE EXCEPTION 'BACKUP_CONTRACT_DEFAULT_ACL_MISSING';
  END IF;
END;
$assert_backup_contract$;

COMMIT;
